 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);ap.add_argument('--commit',required=True);a=ap.parse_args();r=a.root;d=json.loads((r/'results/run_provenance_v83.json').read_text());d['schema']='run_provenance_v84';d['created_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();d['github_main_commit']=a.commit;d['source_alignment']='results/main_nersc_source_alignment_v43.json';d['source_alignment_sha256']=sha(r/'results/main_nersc_source_alignment_v43.json');d['stage_progress']='results/stage_progress_v28.json';d['stage_progress_sha256']=sha(r/'results/stage_progress_v28.json');d['stage8_holdout_report']='results/stage8_holdout_validation_report_v11.json';d['stage8_holdout_report_sha256']=sha(r/'results/stage8_holdout_validation_report_v11.json');d['primordial_finitebox_audit']='results/primordial_mu2_trispectrum_component_audit_v2.json';d['primordial_finitebox_audit_sha256']=sha(r/'results/primordial_mu2_trispectrum_component_audit_v2.json');d['batch_outputs']['source_alignment_v43']='results/main_nersc_source_alignment_v43.json';d['batch_outputs']['stage_progress_v28']='results/stage_progress_v28.json';d['batch_outputs']['stage8_holdout_report_v11']='results/stage8_holdout_validation_report_v11.json';d['batch_outputs']['primordial_finitebox_audit']='results/primordial_mu2_trispectrum_component_audit_v2.json';d['status']='PARTIAL';a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(d,indent=2)+'\n');print(json.dumps({'status':d['status'],'commit':a.commit}))
